B.am=s([],t.zr)
B.WD=s(["Th..Thank you, Mateo. I..I owe you my life...","The words grow distant as exhaustion pulls you back into darkness."],t.s)
B.NT=new A.cs("Close your eyes","intro_pass_out_to_spanish_home",!0,!1)
