B.NO=new A.cs("Choose your name","intro_choose_player_name",!0,!1)
B.Uy=s([B.NO],t.u)
B.OB=new A.ci(B.am,B.X8,null,null,null,B.Uy)
B.U3=s([B.OB],t.J)
B.O2=new A.cN("Concerned Stranger",B.U3)
B.UX=s(["Welcome, captain. Your ship has good bones, but there is always room for finer work.","Would you like to order work on your ship?"],t.s)
B.NL=new A.cs("View ship upgrades","open_ship_upgrade_menu",!1,!0)
B.Xc=s([B.NL,B.fX],t.u)
